# (title, text, quote, source)

SCIENCE_EN = [
 ("Find your why", "Begin with the end in mind: with this habit, who will you grow into?", "Every action is a vote for the type of person you wish to become.", "James Clear, Atomic Habits"),
 ("Make it tiny", "Start by making your habit tiny and practice the art of showing up for it. Later, you'll let it grow.", "Keeping the habit alive means keeping it rooted in your routine no matter how tiny it is.", "BJ Fogg, Tiny Habits"),
 ("Don't break the chain", "Your habit is growing step by step, day by day. You're adding rings to the chain.", "Don't-break-the-chain is a powerful strategy.", "Gretchen Rubin, Better Than Before"),
 ("Find what works for you", "Your daily life is the soil in which your habit is taking root: make sure they are made for each other.", "To shape our habits successfully, we must know ourselves.", "Gretchen Rubin, Better Than Before"),
 ("Design an implementation intention", "Invite your habit like you invite a friend: be precise with when and where.", "Give your habits a time and a space to live in the world.", "James Clear, Atomic Habits"),
 ("Make it visible", "Give your habit presence: choose a visible cue that will greet you each day.", "No behavior happens without a prompt.", "BJ Fogg, Tiny Habits"),
 ("Use temptation bundling", "Pick an activity you enjoy, the carrot, and pair it with your habit.", "When dopamine rises, so does our motivation to act.", "James Clear, Atomic Habits"),
 ("Enter into a habit contract", "Find an accountability partner: a friend who will offer tough love and cupcakes of encouragement.", "When another pair of eyes is watching, we feel as if the magnitude of whatever we're doing has multiplied.", "Ayelet Fishbach, Get It Done"),
 ("Prime your environment", "Design your habit with the lazy days in mind. How easy can you make it? What hurdles can you remove?", "Make it easy to do right, and hard to go wrong.", "Gretchen Rubin, Better Than Before"),
 ("Be gentle", "Your habit is alive, let it flex with life. A little self-kindness keeps it sustainable.", "Too much rigidity is the enemy of a good habit.", "Katy Milkman, How to Change"),
 ("Use habit stacking", "Pick a habit you already have and make it a cue for your new habit. The new one will piggyback on the existing one.", "You already have an entire ecosystem of routines humming along nicely; you just have to tap into it.", "BJ Fogg, Tiny Habits"),
 ("Celebrate", "Find a tiny treat that feels good and let yourself have it right after your habit.", "Emotions create habits. Not repetition. Not frequency. Not fairy dust. Emotions.", "BJ Fogg, Tiny Habits"),
 ("Never miss twice", "A missed day is a pause, not an ending. Whatever happens, come back to your habit the very next day.", "Missing once is an accident. Missing twice is the start of a new habit.", "James Clear, Atomic Habits"),
 ("Do it publicly", "Add a pinch of positive social pressure to your habit: let people know.", "If you believe that others are rooting for your success and keeping an eye on your behavior, you'll be more motivated to do the right thing.", "Kelly McGonigal, The Willpower Instinct"),
 ("Create a positive environment", "Can you simplify, beautify your surroundings?", "A clean, well-maintained environment helps to foster a sense of self-command, which in turn makes it easier to maintain good habits.", "Gretchen Rubin, Better Than Before"),
 ("Let a good habit break a bad one", "Your good habit may be coming in place of a bad one, encourage this shift.", "How to break a bad habit: make it invisible, make it unattractive, make it difficult.", "James Clear, Atomic Habits"),
 ("Surround yourself", "Spend time with friends who already have your habit and will support you.", "Be in good company when you hope to achieve big goals.", "Katy Milkman, How to Change"),
 ("Design safeguards", "Life will get in the way of your habit. Prepare if-then plans so that your life and your habit can remain good friends.", "Predict how and when you might be tempted to break your vow, and imagine a specific plan of action for not giving in.", "Kelly McGonigal, The Willpower Instinct"),
 ("Benefit others", "Picture the fruits of your habit and who they will benefit.", "As you breathe in, cherish yourself. As you breathe out, cherish all beings.", "Dalai Lama"),
 ("Make success visible", "Your 21-day challenge is soon over, congrats! Keep counting your successes with a tick or a number in your calendar.", "If we want something to count in our lives, we should figure out a way to count it.", "Gretchen Rubin, Better Than Before"),
 ("Expect more", "Keep your habit fresh and fun: scale it up, bring variety into it.", "The greatest threat to success is not failure but boredom.", "James Clear, Atomic Habits"),
]

SCIENCE_LT = [
 ("Rask savo „kodėl“", "Pradėk nuo pabaigos: kokiu žmogumi šis įprotis padės tau tapti?", "Kiekvienas veiksmas yra balsas už tą žmogų, kuriuo nori tapti.", "James Clear, Atomic Habits"),
 ("Padaryk jį mažytį", "Pradėk nuo mažyčio įpročio ir mokykis kasdien jam skirti bent akimirką. Vėliau leisi jam augti.", "Išlaikyti įprotį gyvą reiškia išlaikyti jį įsišaknijusį tavo rutinoje, kad ir koks mažas jis būtų.", "BJ Fogg, Tiny Habits"),
 ("Nenutrauk grandinės", "Tavo įprotis auga žingsnis po žingsnio, diena po dienos. Tu pridedi grandinei naujų grandžių.", "„Nenutrauk grandinės“ yra galinga strategija.", "Gretchen Rubin, Better Than Before"),
 ("Atrask, kas tinka tau", "Tavo kasdienybė yra dirva, kurioje šaknis leidžia tavo įprotis: pasirūpink, kad jie derėtų vienas prie kito.", "Kad sėkmingai formuotume įpročius, turime pažinti save.", "Gretchen Rubin, Better Than Before"),
 ("Sukurk įgyvendinimo ketinimą", "Pakviesk savo įprotį taip, kaip kviestum draugą: tiksliai nurodyk, kada ir kur.", "Suteik savo įpročiams laiką ir vietą gyventi pasaulyje.", "James Clear, Atomic Habits"),
 ("Padaryk jį matomą", "Suteik įpročiui buvimo: pasirink matomą ženklą, kuris tave pasitiks kiekvieną dieną.", "Joks elgesys neįvyksta be paskatos.", "BJ Fogg, Tiny Habits"),
 ("Susiek jį su malonumu", "Pasirink veiklą, kuri tau patinka, savo morką, ir susiek ją su įpročiu.", "Kai kyla dopaminas, kyla ir mūsų motyvacija veikti.", "James Clear, Atomic Habits"),
 ("Sudaryk įpročio sutartį", "Susirask atskaitomybės partnerį: draugą, kuris pasiūlys griežtos meilės ir padrąsinimo keksiukų.", "Kai į mus žiūri dar viena akių pora, jaučiamės tarsi to, ką darome, reikšmė būtų padidėjusi.", "Ayelet Fishbach, Get It Done"),
 ("Paruošk aplinką", "Kurk įprotį taip, kad jis atlaikytų ir tingias dienas. Kiek lengvą gali jį padaryti? Kokias kliūtis gali pašalinti?", "Padaryk taip, kad būtų lengva elgtis teisingai ir sunku suklysti.", "Gretchen Rubin, Better Than Before"),
 ("Švelniai su savimi", "Tavo įprotis gyvas, leisk jam lankstytis kartu su gyvenimu. Truputis gerumo sau padeda jam išlikti.", "Per didelis griežtumas yra gero įpročio priešas.", "Katy Milkman, How to Change"),
 ("Uždėk naują įprotį ant seno", "Pasirink įprotį, kurį jau turi, ir paversk jį ženklu naujam įpročiui. Naujasis keliaus ant senojo pečių.", "Tu jau turi visą ekosistemą sklandžiai veikiančių rutinų; tereikia ja pasinaudoti.", "BJ Fogg, Tiny Habits"),
 ("Švęsk", "Rask mažytį malonumą, kuris tau patinka, ir leisk sau jį patirti iškart po įpročio.", "Įpročius kuria emocijos. Ne kartojimas. Ne dažnumas. Ne stebuklingos dulkės. Emocijos.", "BJ Fogg, Tiny Habits"),
 ("Niekada nepraleisk dukart", "Praleista diena yra pauzė, o ne pabaiga. Kad ir kas nutiktų, grįžk prie įpročio jau kitą dieną.", "Praleisti kartą yra atsitiktinumas. Praleisti dukart yra naujo įpročio pradžia.", "James Clear, Atomic Habits"),
 ("Daryk tai viešai", "Pridėk žiupsnelį teigiamo socialinio spaudimo: papasakok kitiems.", "Jei tiki, kad kiti palaiko tavo sėkmę ir stebi tavo elgesį, turėsi daugiau motyvacijos elgtis teisingai.", "Kelly McGonigal, The Willpower Instinct"),
 ("Kurk teigiamą aplinką", "Ar gali supaprastinti ir pagražinti savo aplinką?", "Švari, prižiūrėta aplinka padeda puoselėti savikontrolės jausmą, o tai savo ruožtu palengvina gerų įpročių išlaikymą.", "Gretchen Rubin, Better Than Before"),
 ("Tegul geras įprotis išstumia blogą", "Galbūt tavo geras įprotis ateina vietoj blogo; paskatink šį pokytį.", "Kaip atsikratyti blogo įpročio: padaryk jį nematomą, nepatrauklų ir sunkų.", "James Clear, Atomic Habits"),
 ("Apsupk save tinkamais žmonėmis", "Leisk laiką su draugais, kurie jau turi šį įprotį ir tave palaikys.", "Kai sieki didelių tikslų, būk geroje draugijoje.", "Katy Milkman, How to Change"),
 ("Numatyk apsaugas", "Gyvenimas trukdys tavo įpročiui. Pasiruošk „jei…, tai…“ planus, kad tavo gyvenimas ir įprotis liktų geri draugai.", "Numatyk, kaip ir kada gali kilti pagunda sulaužyti pažadą, ir įsivaizduok konkretų veiksmų planą, kaip jai nepasiduoti.", "Kelly McGonigal, The Willpower Instinct"),
 ("Nešk naudą kitiems", "Įsivaizduok savo įpročio vaisius ir tuos, kam jie bus naudingi.", "Įkvėpdamas brangink save. Iškvėpdamas brangink visas būtybes.", "Dalai Lama"),
 ("Padaryk sėkmę matomą", "Tavo 21 dienos iššūkis netrukus baigsis, sveikinu! Toliau skaičiuok savo sėkmes kalendoriuje varnele ar skaičiumi.", "Jei norime, kad kažkas mūsų gyvenime iš tiesų skaičiuotųsi, turime rasti būdą tai skaičiuoti.", "Gretchen Rubin, Better Than Before"),
 ("Tikėkis daugiau", "Išlaikyk įprotį gyvą ir smagų: didink jį, įnešk įvairovės.", "Didžiausia grėsmė sėkmei yra ne nesėkmė, o nuobodulys.", "James Clear, Atomic Habits"),
]

AGING_EN = [
 ("Honor your body's journey", "Start with gratitude for your body and the life it has enabled you to live.", "Cherish your body; it is yours for this one time only.", "Jack Kornfield, After the Ecstasy, the Laundry"),
 ("Rest to restore", "Deep, regular sleep helps protect memory, immune health, and mood. Create a calming pre-sleep ritual and aim for 7 to 8 hours each night.", "Just like exercise, sleep is its own kind of wonder drug.", "Peter Attia, Outlive"),
 ("Nourish from within", "Lean toward whole foods linked to slower cellular aging: leafy greens, berries, olive oil, nuts. Drink plenty of water.", "The best approximation for an anti-wrinkle diet is one that’s centered around whole plant foods.", "Michael Greger, How Not to Age"),
 ("Move your body joyfully", "Walk, stretch, or dance each day, not to fix your body, but to enjoy living in it.", "Embrace the reality that movement is as important as brushing your teeth.", "Gabrielle Lyon, Forever Strong"),
 ("Rethink aging", "Replace ‘getting old’ with ‘growing wise’. Seeing aging as a time of expansion, not decline, lifts your well-being.", "Even if we are the product of the past, we are still the architects of our future.", "Matthieu Ricard, Beyond the Self"),
 ("Declutter your space and mind", "Clear physical and mental clutter to reduce stress. Let go of what no longer serves you, from outdated beliefs to unused possessions.", "We don’t need to believe everything our thoughts tell us.", "Elizabeth Blackburn, The Telomere Effect"),
 ("Build and keep your strength", "Add two short strength sessions this week: bodyweight, bands, or weights all count. Strength isn't about how you look: it's what keeps you independent as you age.", "The currency of healthy aging is muscle—lean, high-performance muscle.", "Mark Hyman, Young Forever"),
 ("Cultivate emotional agility", "Practice noticing your emotions without being ruled by them. This flexibility supports your mental health and gentler relationships.", "The aim is not to cease to experience emotions but to avoid being enslaved by them.", "Matthieu Ricard, Beyond the Self"),
 ("Embrace imperfection", "Talk to yourself as you would to a friend. Be gentle with your inner critic: a harsh inner voice can weigh on you more than the years.", "The point is not to perfect yourself. It is to perfect your love.", "Jack Kornfield, No Time Like the Present"),
 ("Laugh and lighten up", "Watch something funny, recall a ridiculous memory, or laugh with a friend. Lightness is medicine.", "Add humor, hugs, and laughter.", "Linda Bacon, Body Respect"),
 ("Accept what is", "Notice resistance to change. Practice softening around it. Acceptance isn't resignation: it's clarity.", "Hell is resistance. Heaven is acceptance.", "Stephen Levine, Who Dies?"),
 ("Nurture a soul practice", "Journal, pray, chant, or sit in nature. Caring for your soul deepens resilience and joy as you age.", "Life purpose is what brings us eudaemonic happiness, the healthy feeling that we are involved in something bigger than ourselves.", "Elizabeth Blackburn, The Telomere Effect"),
 ("Tend to your daily rhythm", "Choose one small part of your day to improve: how you eat, move, rest, or connect. Small shifts, big ripples.", "There is always a step small enough from where we are to get us to where we want to be.", "Ellen Langer, Counterclockwise"),
 ("Strengthen true connection", "Reach out and let yourself be vulnerable. Share a story. Be seen and heard. Aging well includes loving well.", "Evidently, a loving brain lives a happier and longer life.", "Lisa Mosconi, Brain Food"),
 ("Cultivate presence", "Take 10 to 15 minutes to simply sit and observe your breath, thoughts, and feelings without judgment. Eat one mindful meal today without distractions.", "The present moment is filled with joy and happiness. If you are attentive, you will see it.", "Thich Nhat Hanh, Peace Is Every Step"),
 ("Express yourself creatively", "Write, paint, play, or dance. Creative play is food for the soul and mind.", "Pen your poem, dance your dance, express the depths of your own heart.", "Jack Kornfield, No Time Like the Present"),
 ("Share your wisdom", "Mentor, volunteer, or simply tell stories. Your legacy takes shape in how you show up, starting today.", "I’m holding on to my torch. I’ll let other people light theirs from mine.", "Daniel Levitin, Successful Aging"),
 ("Keep learning, keep growing", "Curiosity is youthfulness in disguise. Try or learn one new thing today: a language, an instrument, a skill. Your brain keeps its power to learn far longer than we think.", "You are never too old to set another goal or to dream a new dream.", "L. Brown in Mark Hyman, Young Forever"),
 ("Practice forgiveness", "Identify one grudge or resentment you're holding. Take a first step toward forgiveness, not for the other person, but for your own freedom and peace.", "Every day I make mistakes, and every day I try to forgive myself for them.", "Peter Attia, Outlive"),
 ("Connect with nature", "Spend 20 minutes outdoors mindfully: walk in a park, sit by water, or garden. Time in nature reduces stress and supports well-being.", "Don’t hold yourself captive; get out there and bathe in nature!", "Max Lugavere, The Genius Life"),
 ("Accept the limits", "Some things about growing older can only be met with grace: less speed, less energy, less certainty. The aging body, the slower pace. This is memento mori.", "We need to learn to see our physical form as a river. Our body is not a static thing—it changes all the time.", "Thich Nhat Hanh, You Are Here"),
]

AGING_LT = [
 ("Pagerbk savo kūno kelionę", "Pradėk nuo dėkingumo savo kūnui ir gyvenimui, kurį jis tau leido nugyventi.", "Brangink savo kūną; jis tau duotas tik šį vienintelį kartą.", "Jack Kornfield, After the Ecstasy, the Laundry"),
 ("Ilsėkis, kad atsigautum", "Gilus, reguliarus miegas padeda saugoti atmintį, imunitetą ir nuotaiką. Susikurk raminantį ritualą prieš miegą ir siek 7–8 valandų miego kas naktį.", "Kaip ir fizinis aktyvumas, miegas yra savotiški stebuklingi vaistai.", "Peter Attia, Outlive"),
 ("Maitink save iš vidaus", "Rinkis natūralų, neperdirbtą maistą, kuris, kaip įrodyta, lėtina ląstelių senėjimą: lapines daržoves, uogas, alyvuogių aliejų, riešutus. Gerk daug vandens.", "Geriausia mityba prieš raukšles yra ta, kurios pagrindas yra neperdirbti augaliniai produktai.", "Michael Greger, How Not to Age"),
 ("Judėk su džiaugsmu", "Kasdien vaikščiok, tempkis ar šok: ne tam, kad pataisytum savo kūną, o dėl džiaugsmo jame gyventi.", "Priimk tai, kad judėjimas yra toks pat svarbus kaip dantų valymas.", "Gabrielle Lyon, Forever Strong"),
 ("Permąstyk senėjimą", "Pakeisk „senstu“ į „išmintingėju“. Senėjimą suvokiant kaip plėtros, o ne nuosmukio etapą, stiprėja psichologinė gerovė.", "Net jei esame praeities padarinys, vis tiek esame savo ateities architektai.", "Matthieu Ricard, Beyond the Self"),
 ("Išvalyk erdvę ir mintis", "Atsikratyk fizinės ir mentalinės netvarkos, kad sumažintum stresą. Paleisk tai, kas nebetarnauja: nuo pasenusių įsitikinimų iki nenaudojamų daiktų.", "Neprivalome tikėti viskuo, ką mums sako mūsų mintys.", "Elizabeth Blackburn, The Telomere Effect"),
 ("Ugdyk ir išlaikyk jėgą", "Šią savaitę pridėk dvi trumpas jėgos treniruotes: tinka ir savo kūno svoris, ir gumos, ir svoriai. Jėga svarbi ne dėl išvaizdos; ji saugo tavo savarankiškumą senstant.", "Sveiko senėjimo valiuta yra raumenys: liesi, didelio pajėgumo raumenys.", "Mark Hyman, Young Forever"),
 ("Ugdyk emocinį lankstumą", "Mokykis stebėti emocijas ir neleisti joms tavęs valdyti. Emocinis lankstumas stiprina psichikos sveikatą ir darnius santykius.", "Tikslas nėra nustoti jausti emocijas, o nebūti jų vergais.", "Matthieu Ricard, Beyond the Self"),
 ("Priimk netobulumą", "Kalbėk su savimi taip, kaip kalbėtum su draugu. Su vidiniu kritiku elkis švelniai: jis sendina labiau nei laikas.", "Esmė ne ištobulinti save. Esmė ištobulinti savo meilę.", "Jack Kornfield, No Time Like the Present"),
 ("Juokis ir palengvėk", "Pažiūrėk ką nors juokingo, prisimink kokią nors kvailą akimirką ar pasijuok su draugu. Lengvumas yra vaistas.", "Pridėk humoro, apkabinimų ir juoko.", "Linda Bacon, Body Respect"),
 ("Priimk tai, kas yra", "Pastebėk, kaip priešiniesi pokyčiams. Mokykis tame atsipalaiduoti. Priėmimas nėra nuolankumas; tai aiškumas.", "Pragaras yra priešinimasis. Rojus yra priėmimas.", "Stephen Levine, Who Dies?"),
 ("Puoselėk sielos praktiką", "Rašyk dienoraštį, melskis, pabūk gamtoje (nepamiršk apsaugos nuo saulės) ar giedok. Sielos priežiūra stiprina atsparumą ir džiaugsmą senstant.", "Gyvenimo tikslas suteikia mums eudaimonišką laimę: sveiką jausmą, kad esame dalis kažko didesnio už save.", "Elizabeth Blackburn, The Telomere Effect"),
 ("Prižiūrėk savo dienos ritmą", "Peržvelk ir pagerink vieną mažą savo dienos dalį: kaip valgai, judi, ilsiesi, bendrauji. Maži pokyčiai, dideli ratilai.", "Visada yra pakankamai mažas žingsnis, kuris nuves mus iš ten, kur esame, ten, kur norime būti.", "Ellen Langer, Counterclockwise"),
 ("Stiprink tikrą ryšį", "Atsiverk. Papasakok savo istoriją. Leisk save pamatyti ir išgirsti. Gražiai senti reiškia ir gražiai mylėti.", "Akivaizdu, kad mylinčios smegenys gyvena laimingiau ir ilgiau.", "Lisa Mosconi, Brain Food"),
 ("Ugdyk dėmesingą buvimą", "Skirk 10–15 minučių tiesiog sėdėti ir stebėti savo kvėpavimą, mintis ir jausmus be vertinimo. Šiandien suvalgyk vieną patiekalą dėmesingai, be jokių trukdžių.", "Dabarties akimirka pilna džiaugsmo ir laimės. Jei atkreipsi dėmesį, tai pamatysi.", "Thich Nhat Hanh, Peace Is Every Step"),
 ("Išreikšk save kūrybiškai", "Rašyk, piešk, grok ar šok. Kūrybinis žaismas yra peno sielai ir protui.", "Parašyk savo eilėraštį, šok savo šokį, išreikšk savo širdies gelmes.", "Jack Kornfield, No Time Like the Present"),
 ("Dalinkis išmintimi", "Būk mentoriumi, savanoriauk ar tiesiog pasakok istorijas. Pradėk kurti savo palikimą tuo, kaip rodaisi pasauliui, jau nuo šiandien.", "Aš laikau savo fakelą. Leisiu kitiems nuo jo užsidegti savuosius.", "Daniel Levitin, Successful Aging"),
 ("Mokykis ir augk", "Smalsumas yra užsimaskavęs jaunatviškumas. Šiandien išbandyk ar išmok ką nors naujo: kalbą, instrumentą ar įgūdį. Neuroplastiškumas nesensta taip, kaip manome.", "Niekada nesi per senas išsikelti naują tikslą ar susapnuoti naują svajonę.", "Mark Hyman, Young Forever"),
 ("Praktikuok atleidimą", "Įvardyk vieną nuoskaudą ar pagiežą, kurią nešiojiesi. Pradėk atleidimo procesą: ne dėl kitų, o dėl savo laisvės ir ramybės.", "Kasdien darau klaidų ir kasdien stengiuosi sau už jas atleisti.", "Peter Attia, Outlive"),
 ("Susijunk su gamta", "Praleisk 20 minučių lauke dėmesingai: pasivaikščiok parke, pasėdėk prie vandens ar padirbėk sode. Ryšys su gamta mažina stresą ir gerina savijautą.", "Nelaikyk savęs nelaisvėje; eik laukan ir maudykis gamtoje!", "Max Lugavere, The Genius Life"),
 ("Priimk ribas", "Kai kuriuos senėjimo dalykus galima pasitikti tik su malone: mažiau greičio, mažiau energijos, mažiau tikrumo. Senstantis kūnas, lėtesnis tempas. Tai memento mori.", "Turime išmokti matyti savo fizinį pavidalą kaip upę. Mūsų kūnas nėra statiškas; jis nuolat keičiasi.", "Thich Nhat Hanh, You Are Here"),
]

